func UpdatedAtLT(v time.Time) predicate.GalleryCache {
	return predicate.GalleryCache(sql.FieldLT(FieldUpdatedAt, v))
}

// UpdatedAtLTE applies the LTE predicate on the "updated_at" field.
func UpdatedAtLTE(v time.Time) predicate.GalleryCache {
	return predicate.GalleryCache(sql.FieldLTE(FieldUpdatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GalleryCache) predicate.GalleryCache {
	return predicate.GalleryCache(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GalleryCache) predicate.GalleryCache {
	return predicate.GalleryCache(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GalleryCache) predicate.GalleryCache {
	return predicate.GalleryCache(sql.NotPredicates(p))
}
